public class DOMNodePointer_getValue_TriageGen0Test {

    @Test
    public void testGetValue_WithTextNode() throws Exception {
        // Setup a real DOM structure to test the underlying stringValue(node) logic
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Element root = doc.createElement("root");
        doc.appendChild(root);
        Text textNode = doc.createTextNode("Hello JXPath");
        root.appendChild(textNode);

        // DOMNodePointer(Node node, Locale locale)
        DOMNodePointer pointer = new DOMNodePointer(textNode, Locale.ENGLISH);

        // Act
        Object value = pointer.getValue();

        // Assert
        assertEquals("Hello JXPath", value);
    }

    @Test
    public void testGetValue_WithElementNode() throws Exception {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Element root = doc.createElement("root");
        Element child = doc.createElement("child");
        child.appendChild(doc.createTextNode("Content"));
        root.appendChild(child);
        doc.appendChild(root);

        // Testing getValue on an Element should return the concatenated text of its children
        DOMNodePointer pointer = new DOMNodePointer(child, Locale.ENGLISH);

        // Act
        Object value = pointer.getValue();

        // Assert
        assertEquals("Content", value);
    }

    @Test
    public void testGetValue_WithEmptyElement() throws Exception {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Element root = doc.createElement("root");
        doc.appendChild(root);

        DOMNodePointer pointer = new DOMNodePointer(root, Locale.ENGLISH);

        // Act
        Object value = pointer.getValue();

        // Assert (Empty element usually returns empty string via stringValue)
        assertEquals("", value);
    }

    @Test
    public void testGetValue_WithNullNode() {
        // Depending on implementation, passing null might throw NPE or return null
        // Given the signature, we test the behavior with a null-initialized context if possible
        // However, the constructor requires a Node. We simulate a pointer that might wrap null if allowed.
        // Since we can't pass null to the constructor based on the provided signature without risking NPE in constructor,
        // we focus on the valid DOM nodes.
    }

    @Test
    public void testGetValue_WithAttributeNode() throws Exception {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Element root = doc.createElement("root");
        root.setAttribute("attr", "attrValue");
        doc.appendChild(root);

        Node attrNode = root.getAttributes().item(0);
        DOMNodePointer pointer = new DOMNodePointer(attrNode, Locale.ENGLISH);

        // Act
        Object value = pointer.getValue();

        // Assert
        assertEquals("attrValue", value);
    }

    @Test
    public void testGetValue_WithComplexNestedStructure() throws Exception {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Element root = doc.createElement("root");
        Element child1 = doc.createElement("c1");
        child1.appendChild(doc.createTextNode("A"));
        Element child2 = doc.createElement("c2");
        child2.appendChild(doc.createTextNode("B"));
        root.appendChild(child1);
        root.appendChild(child2);
        doc.appendChild(root);

        DOMNodePointer pointer = new DOMNodePointer(root, Locale.ENGLISH);

        // Act
        Object value = pointer.getValue();

        // Assert (stringValue usually aggregates text content)
        assertEquals("AB", value);
    }
}
